// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/health", wrapper.GetHealth)
	router.GET(options.BaseURL+"/ready", wrapper.GetReady)
	router.DELETE(options.BaseURL+"/api/v1/me", wrapper.DeleteMe)
	router.GET(options.BaseURL+"/api/v1/me", wrapper.GetMe)
	router.PATCH(options.BaseURL+"/api/v1/me", wrapper.PatchMe)
	router.GET(options.BaseURL+"/api/v1/me/activities", wrapper.ListMyActivities)
	router.GET(options.BaseURL+"/api/v1/me/activities/summary", wrapper.GetMyActivitySummary)
	router.GET(options.BaseURL+"/api/v1/me/activities/weeks", wrapper.ListMyActivityWeeks)
	router.GET(options.BaseURL+"/api/v1/sports", wrapper.GetSports)
	router.GET(options.BaseURL+"/api/v1/challenges", wrapper.ListChallenges)
	router.POST(options.BaseURL+"/api/v1/challenges", wrapper.CreateChallenge)
	router.DELETE(options.BaseURL+"/api/v1/challenges/:challengeId", wrapper.DeleteChallenge)
	router.GET(options.BaseURL+"/api/v1/challenges/:challengeId", wrapper.GetChallenge)
	router.PATCH(options.BaseURL+"/api/v1/challenges/:challengeId", wrapper.UpdateChallenge)
	router.POST(options.BaseURL+"/api/v1/challenges/:challengeId/join", wrapper.JoinChallenge)
	router.POST(options.BaseURL+"/api/v1/challenges/:challengeId/abandon", wrapper.AbandonChallenge)
	router.GET(options.BaseURL+"/api/v1/challenges/:challengeId/participants", wrapper.ListParticipants)
	router.GET(options.BaseURL+"/api/v1/challenges/:challengeId/leaderboard", wrapper.GetLeaderboard)
	router.DELETE(options.BaseURL+"/api/v1/challenges/:challengeId/participants/:userId", wrapper.ExcludeParticipant)
	router.GET(options.BaseURL+"/api/v1/challenges/:challengeId/participants/:userId/activities", wrapper.ListParticipantActivities)
	router.GET(options.BaseURL+"/api/v1/challenges/:challengeId/activities", wrapper.ListChallengeActivities)
	router.POST(options.BaseURL+"/api/v1/challenges/:challengeId/creators", wrapper.AddCreator)
	router.POST(options.BaseURL+"/api/v1/challenges/:challengeId/invitations", wrapper.CreateInvitation)
	router.POST(options.BaseURL+"/api/v1/invitations/open", wrapper.OpenInvitation)
	router.POST(options.BaseURL+"/api/v1/invitations/accept", wrapper.AcceptInvitation)
	router.POST(options.BaseURL+"/api/v1/activities", wrapper.CreateActivity)
	router.DELETE(options.BaseURL+"/api/v1/activities/:activityId", wrapper.DeleteActivity)
	router.PATCH(options.BaseURL+"/api/v1/activities/:activityId", wrapper.UpdateActivity)
}

